-- Bütçe kalemleri için başlangıç (departman + kalem) verisi ve
-- Arçelik'in gerçek "Niteliklerine Göre Giderler" dipnotundan üretilmiş
-- aylık gerçekleşen değerler (2016-2025)
-- Önce schema_mssql.sql çalıştırılmış ve ButceTahmin veritabanı seçili olmalı.


SELECT N'Hammadde ve Malzeme Gideri', id, 'Gider', N'KAP finansal tablo dipnotu: Hammadde, malzeme ve ticari mallar'
FROM departman WHERE ad = N'Arçelik Örnek Şirket - Genel Merkez';

SELECT N'Personel Giderleri', id, 'Gider', N'KAP finansal tablo dipnotu: Personel giderleri'
FROM departman WHERE ad = N'Arçelik Örnek Şirket - Genel Merkez';

SELECT N'Enerji Giderleri', id, 'Gider', N'2016-2019 KAP dipnotundan gerçek; 2020-2025 tahmini (bkz. not)'
FROM departman WHERE ad = N'Arçelik Örnek Şirket - Genel Merkez';

SELECT N'Pazarlama Giderleri', id, 'Gider', N'KAP finansal tablo dipnotu: Reklam, tanıtım ve promosyon giderleri (proxy)'
FROM departman WHERE ad = N'Arçelik Örnek Şirket - Genel Merkez';

-- Arcelik gercek yillik verisinden mevsimsel dagitimla uretilmis aylik GerceklesenDeger kayitlari
-- Hammadde, Personel, Pazarlama: 2016-2025 tamami GERCEK yillik toplamdan dagitilmistir (KAP finansal tablo dipnotu)
-- Enerji: 2016-2019 GERCEK; 2020-2025 TAHMINI (enerji/hammadde ortalama orani ile) - kaynak degil, yaklasik degerdir

